CREATE OR REPLACE FUNCTION public.cancel_scheduled_message(schedule_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null then raise exception 'Sign in required.';end if;
 update public.scheduled_messages set status='cancelled' where id=schedule_id and sender_id=auth.uid() and status='pending';return found;
end;$function$
CREATE OR REPLACE FUNCTION public.cast_chat_poll_vote(target_poll_id uuid, target_option_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  voter uuid := auth.uid();
  poll_row public.chat_polls%rowtype;
  option_count integer;
  unique_option_count integer;
begin
  if voter is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if target_option_ids is null
     or cardinality(target_option_ids) < 1
     or cardinality(target_option_ids) > 30 then
    raise exception 'Choose between 1 and 30 options' using errcode = '22023';
  end if;

  select * into poll_row
  from public.chat_polls p
  where p.id = target_poll_id
  for update;

  if not found then
    raise exception 'Poll not found' using errcode = 'P0002';
  end if;
  if not public.is_conversation_member(poll_row.conversation_id) then
    raise exception 'Not a conversation member' using errcode = '42501';
  end if;
  if poll_row.closes_at is not null and poll_row.closes_at <= now() then
    raise exception 'Poll is closed' using errcode = '22023';
  end if;

  select count(*), count(distinct x.option_id)
  into option_count, unique_option_count
  from unnest(target_option_ids) as x(option_id)
  join public.chat_poll_options o
    on o.id = x.option_id and o.poll_id = target_poll_id;

  if option_count <> cardinality(target_option_ids)
     or unique_option_count <> cardinality(target_option_ids) then
    raise exception 'Invalid or duplicate poll option' using errcode = '22023';
  end if;
  if not poll_row.multiple_choice and cardinality(target_option_ids) <> 1 then
    raise exception 'This poll allows one choice only' using errcode = '22023';
  end if;

  if not poll_row.multiple_choice then
    delete from public.chat_poll_votes v
    where v.poll_id = target_poll_id and v.user_id = voter;
  end if;

  insert into public.chat_poll_votes(poll_id, option_id, user_id)
  select target_poll_id, x.option_id, voter
  from unnest(target_option_ids) as x(option_id)
  on conflict (poll_id, option_id, user_id) do nothing;

  return jsonb_build_object('poll_id', target_poll_id, 'saved', true);
end;
$function$
