CREATE OR REPLACE FUNCTION public.consume_auth_action_limit(action_name text, email_digest text, ip_digest text, max_email integer DEFAULT 5, max_ip integer DEFAULT 20, window_minutes integer DEFAULT 60)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare email_count integer; ip_count integer; begin if $1 not in ('password_reset','resend_confirmation','signin') or $2 is null or length($2) <> 64 or $3 is null or length($3) <> 64 or $4 < 1 or $5 < 1 or $6 < 1 or $6 > 1440 then return false; end if; perform pg_advisory_xact_lock(hashtext($1 || $2), hashtext($3)); select count(*) into email_count from public.auth_action_attempts a where a.action_name = $1 and a.email_hash = $2 and a.attempted_at > now() - make_interval(mins => $6); select count(*) into ip_count from public.auth_action_attempts a where a.action_name = $1 and a.ip_hash = $3 and a.attempted_at > now() - make_interval(mins => $6); if email_count >= $4 or ip_count >= $5 then return false; end if; insert into public.auth_action_attempts(action_name, email_hash, ip_hash) values ($1, $2, $3); delete from public.auth_action_attempts where attempted_at < now() - interval '30 days'; return true; end; $function$
CREATE OR REPLACE FUNCTION public.consume_signup_rate_limit(email_digest text, ip_digest text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  email_count integer;
  ip_count integer;
begin
  if email_digest is null or length(email_digest) <> 64
     or ip_digest is null or length(ip_digest) <> 64 then
    return false;
  end if;

  perform pg_advisory_xact_lock(hashtext(email_digest), hashtext(ip_digest));

  select count(*) into email_count
    from public.auth_signup_attempts
   where email_hash = email_digest
     and attempted_at > now() - interval '1 hour';

  select count(*) into ip_count
    from public.auth_signup_attempts
   where ip_hash = ip_digest
     and attempted_at > now() - interval '1 hour';

  if email_count >= 5 or ip_count >= 20 then
    return false;
  end if;

  insert into public.auth_signup_attempts(email_hash, ip_hash)
  values (email_digest, ip_digest);

  delete from public.auth_signup_attempts
   where attempted_at < now() - interval '30 days';

  return true;
end;
$function$
CREATE OR REPLACE FUNCTION public.create_chat_poll(target_message_id uuid, poll_question text, option_texts text[], poll_kind text DEFAULT 'poll'::text, allow_multiple boolean DEFAULT false, hide_voters boolean DEFAULT false, poll_closes_at timestamp with time zone DEFAULT NULL::timestamp with time zone, correct_option_indexes integer[] DEFAULT '{}'::integer[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid; message_row public.chat_messages; new_poll_id uuid; opt record;
begin
 caller_id := (select auth.uid());
 if caller_id is null then raise exception 'Authentication required'; end if;
 if poll_question is null or char_length(btrim(poll_question)) not between 1 and 500 then raise exception 'Poll question must be 1–500 characters'; end if;
 if poll_kind not in ('poll','quiz','question') then raise exception 'Invalid poll kind'; end if;
 if coalesce(array_length(option_texts,1),0) < 2 or array_length(option_texts,1)>12 then raise exception 'A poll must have 2–12 options'; end if;
 if poll_closes_at is not null and poll_closes_at<=now() then raise exception 'Poll closing time must be in the future'; end if;
 select * into message_row from public.chat_messages m where m.id=target_message_id and m.sender_id=caller_id and m.deleted_at is null;
 if message_row.id is null or not public.is_conversation_member(message_row.conversation_id) then raise exception 'Message not found or access denied'; end if;
 if exists(select 1 from unnest(option_texts) x where char_length(btrim(x)) not between 1 and 300) then raise exception 'Each option must be 1–300 characters'; end if;
 if exists(select 1 from unnest(coalesce(correct_option_indexes,'{}'::integer[])) i where i<1 or i>array_length(option_texts,1)) then raise exception 'Correct option index is invalid'; end if;
 insert into public.chat_polls(message_id,conversation_id,created_by,question,poll_kind,multiple_choice,anonymous,closes_at)
 values(target_message_id,message_row.conversation_id,caller_id,btrim(poll_question),poll_kind,allow_multiple,hide_voters,poll_closes_at)
 returning id into new_poll_id;
 for opt in select value, ordinality::integer as pos from unnest(option_texts) with ordinality as u(value, ordinality)
 loop
  insert into public.chat_poll_options(poll_id,option_text,sort_order)
  values(new_poll_id,btrim(opt.value),opt.pos);
 end loop;
 if poll_kind='quiz' then
  insert into public.chat_poll_correct_answers(poll_id,option_id,created_by)
  select new_poll_id,o.id,caller_id from public.chat_poll_options o
  where o.poll_id=new_poll_id and o.sort_order=any(coalesce(correct_option_indexes,'{}'::integer[]));
 end if;
 return new_poll_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.create_chat_simple_poll(target_conversation_id uuid, poll_question text, option_texts text[], operation_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare msg public.chat_messages;pid uuid;message_text text;
begin
 if coalesce(cardinality(option_texts),0) not between 2 and 8 or exists(select 1 from unnest(option_texts)o where o is null or length(trim(o)) not between 1 and 300) or poll_question is null or length(trim(poll_question)) not between 1 and 500 then raise exception 'Enter a question and 2–8 options.';end if;
 if(select count(distinct lower(trim(o))) from unnest(option_texts)o)<>cardinality(option_texts) then raise exception 'Poll options must be different.';end if;
 message_text:='Poll: '||trim(poll_question)||E'\n'||array_to_string(option_texts,E'\n');
 msg:=public.send_chat_message_idempotent(target_conversation_id,operation_id,message_text,'text',null);
 perform 1 from public.chat_messages where id=msg.id for update;
 select id into pid from public.chat_polls where message_id=msg.id;
 if pid is null then pid:=public.create_chat_poll(msg.id,poll_question,option_texts,'poll',false,false,null,'{}'::integer[]);end if;
 return msg.id;
end;$function$
CREATE OR REPLACE FUNCTION public.create_group_chat(group_title text, member_usernames text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me uuid := auth.uid();
  new_id uuid;
  uname text;
  member_id uuid;
begin
  if me is null then raise exception 'Sign in is required'; end if;
  if nullif(trim(group_title),'') is null or char_length(trim(group_title)) > 100 then
    raise exception 'Group name must be between 1 and 100 characters';
  end if;
  if coalesce(array_length(member_usernames,1),0) > 99 then raise exception 'Too many group members'; end if;
  insert into public.conversations(kind,title,created_by) values ('group',trim(group_title),me) returning id into new_id;
  insert into public.conversation_members(conversation_id,user_id,role) values(new_id,me,'owner');
  foreach uname in array coalesce(member_usernames, array[]::text[]) loop
    select p.id into member_id from public.profiles p where lower(p.username)=lower(trim(uname));
    if member_id is not null and member_id <> me then
      insert into public.conversation_members(conversation_id,user_id,role)
      values(new_id,member_id,'member') on conflict do nothing;
    end if;
  end loop;
  return new_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.dispatch_my_scheduled_messages()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item record; new_message_id uuid; sent_count integer := 0; caller_id uuid;
begin
 caller_id := (select auth.uid());
 if caller_id is null then raise exception 'Authentication required'; end if;
 for item in
  select * from public.scheduled_messages
  where sender_id=caller_id and status='pending' and send_at<=now()
  order by send_at
  for update skip locked
 loop
  if not exists(select 1 from public.conversation_members cm where cm.conversation_id=item.conversation_id and cm.user_id=caller_id) then
   update public.scheduled_messages set status='failed', error_text='Conversation membership no longer exists' where id=item.id;
  else
   insert into public.chat_messages(conversation_id,sender_id,body,message_type,reply_to)
   values(item.conversation_id,caller_id,item.body,item.message_type,item.reply_to)
   returning id into new_message_id;
   update public.scheduled_messages set status='sent', sent_message_id=new_message_id, sent_at=now(), error_text=null where id=item.id;
   sent_count := sent_count+1;
  end if;
 end loop;
 return sent_count;
end;
$function$
CREATE OR REPLACE FUNCTION public.edit_own_message(target_message_id uuid, new_body text)
 RETURNS chat_messages
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare updated_message public.chat_messages;
begin
 if new_body is null or char_length(btrim(new_body))=0 or char_length(new_body)>10000 then
  raise exception 'Message text must contain 1–10000 characters';
 end if;
 update public.chat_messages
 set body=new_body, edited_at=now()
 where id=target_message_id and sender_id=(select auth.uid()) and deleted_at is null and recalled_at is null
 returning * into updated_message;
 if updated_message.id is null then raise exception 'Message not found or cannot be edited'; end if;
 return updated_message;
end;
$function$
