CREATE OR REPLACE FUNCTION public.get_chat_message_extras(target_message_ids uuid[])
 RETURNS TABLE(message_id uuid, reactions jsonb, saved boolean, read_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null then raise exception 'Sign in required.';end if;
 if coalesce(cardinality(target_message_ids),0)>200 then raise exception 'Request up to 200 messages.';end if;
 return query select m.id,
 coalesce((select jsonb_agg(jsonb_build_object('emoji',r.emoji,'count',r.total,'mine',r.mine)) from(select mr.emoji,count(*) total,bool_or(mr.user_id=auth.uid()) mine from public.message_reactions mr where mr.message_id=m.id group by mr.emoji)r),'[]'::jsonb),
 exists(select 1 from public.message_bookmarks b where b.message_id=m.id and b.user_id=auth.uid()),
 case when m.sender_id=auth.uid() then(select count(*) from public.message_receipts receipt left join public.user_chat_settings prefs on prefs.user_id=receipt.user_id where receipt.message_id=m.id and receipt.read_at is not null and coalesce(prefs.read_receipts,true)) else 0::bigint end
 from public.chat_messages m where m.id=any(target_message_ids) and m.deleted_at is null and m.recalled_at is null and(m.expires_at is null or m.expires_at>now()) and public.is_conversation_member(m.conversation_id);
end;$function$
CREATE OR REPLACE FUNCTION public.get_chat_polls(target_message_ids uuid[])
 RETURNS TABLE(message_id uuid, poll_id uuid, question text, options jsonb, closed boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null or coalesce(cardinality(target_message_ids),0)>200 then raise exception 'Invalid request.';end if;
 return query select m.id,p.id,p.question,
 coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'text',o.option_text,'count',(select count(*) from public.chat_poll_votes v where v.poll_id=p.id and v.option_id=o.id),'mine',exists(select 1 from public.chat_poll_votes v where v.poll_id=p.id and v.option_id=o.id and v.user_id=auth.uid())) order by o.sort_order) from public.chat_poll_options o where o.poll_id=p.id),'[]'::jsonb),
 p.closes_at is not null and p.closes_at<=now()
 from public.chat_polls p join public.chat_messages m on m.id=p.message_id where m.id=any(target_message_ids) and public.is_conversation_member(m.conversation_id) and m.deleted_at is null and m.recalled_at is null and(m.expires_at is null or m.expires_at>now());
end;$function$
CREATE OR REPLACE FUNCTION public.get_my_chat_previews()
 RETURNS TABLE(id uuid, conversation_id uuid, body text, created_at timestamp with time zone, sender_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select msg.id,c.id,msg.body,msg.created_at,msg.sender_id
 from public.conversations c join public.conversation_members cm on cm.conversation_id=c.id and cm.user_id=(select auth.uid())
 left join lateral(select m.id,m.body,m.created_at,m.sender_id from public.chat_messages m where m.conversation_id=c.id and m.deleted_at is null and m.recalled_at is null and(m.expires_at is null or m.expires_at>now()) order by m.created_at desc,m.id desc limit 1) msg on true;
$function$
CREATE OR REPLACE FUNCTION public.get_my_conversation_unread_counts()
 RETURNS TABLE(conversation_id uuid, unread_count bigint, last_message_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select cm.conversation_id,count(m.id)::bigint,c.last_message_at from public.conversation_members cm join public.conversations c on c.id=cm.conversation_id left join public.chat_private_read_markers marker on marker.user_id=cm.user_id and marker.conversation_id=cm.conversation_id left join public.chat_messages m on m.conversation_id=cm.conversation_id and m.sender_id<>auth.uid() and m.created_at>coalesce(marker.read_through,cm.last_read_at,'-infinity'::timestamptz) and m.deleted_at is null and m.recalled_at is null and(m.expires_at is null or m.expires_at>now()) where cm.user_id=auth.uid() group by cm.conversation_id,c.last_message_at order by c.last_message_at desc;
$function$
CREATE OR REPLACE FUNCTION public.get_poll_results(target_poll_id uuid)
 RETURNS TABLE(option_id uuid, option_text text, vote_count bigint, is_correct boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare caller_id uuid;
begin
 caller_id := (select auth.uid());
 if caller_id is null then raise exception 'Authentication required'; end if;
 if not exists(select 1 from public.chat_polls p where p.id=target_poll_id and public.is_conversation_member(p.conversation_id)) then
  raise exception 'Poll not found or access denied';
 end if;
 return query
 select o.id,o.option_text,count(v.user_id)::bigint,
        (exists(select 1 from public.chat_poll_correct_answers a where a.poll_id=p.id and a.option_id=o.id and a.created_by=caller_id))
 from public.chat_polls p
 join public.chat_poll_options o on o.poll_id=p.id
 left join public.chat_poll_votes v on v.poll_id=p.id and v.option_id=o.id
 where p.id=target_poll_id
 group by p.id,o.id,o.option_text,o.sort_order
 order by o.sort_order;
end;
$function$
CREATE OR REPLACE FUNCTION public.guard_chat_message_delivery()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not exists(select 1 from public.conversation_members where conversation_id=new.conversation_id and user_id=new.sender_id) then raise exception 'You are not a member of this conversation.' using errcode='42501';end if;
 if exists(select 1 from public.conversations c join public.conversation_members peer on peer.conversation_id=c.id and peer.user_id<>new.sender_id join public.chat_user_blocks b on(b.blocker_id=new.sender_id and b.blocked_id=peer.user_id) or(b.blocker_id=peer.user_id and b.blocked_id=new.sender_id) where c.id=new.conversation_id and c.kind='direct') then raise exception 'Messaging is unavailable for this conversation.' using errcode='42501';end if;
 return new;
end;$function$
CREATE OR REPLACE FUNCTION public.handle_new_chat_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare candidate text; display_label text;
begin
 candidate:=lower(trim(coalesce(new.raw_user_meta_data->>'username','')));
 if candidate !~ '^[a-z0-9_]{3,24}$' then candidate:='luo_'||substr(replace(new.id::text,'-',''),1,16);end if;
 display_label:=coalesce(nullif(left(trim(new.raw_user_meta_data->>'display_name'),80),''),candidate);
 insert into public.profiles(id,username,display_name,bio) values(new.id,candidate,display_label,'') on conflict(id) do nothing;
 return new;
end;$function$
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base_name text; candidate text;
begin
 base_name:=lower(regexp_replace(coalesce(split_part(new.email,'@',1),'luouser'),'[^a-zA-Z0-9_]','','g'));
 if char_length(base_name)<3 then base_name:='luouser'; end if;
 candidate:=left(base_name,23);
 if exists(select 1 from public.profiles p where p.username=candidate) then
  candidate:=left(base_name,20)||'_'||substr(replace(new.id::text,'-',''),1,8);
 end if;
 insert into public.profiles(id,username,display_name)
 values(new.id,candidate,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),candidate))
 on conflict(id) do nothing;
 insert into public.user_chat_settings(user_id) values(new.id) on conflict(user_id) do nothing;
 return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.is_conversation_member(check_conversation_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select exists (select 1 from public.conversation_members cm where cm.conversation_id = check_conversation_id and cm.user_id = (select auth.uid())); $function$
CREATE OR REPLACE FUNCTION public.leave_group(target_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := auth.uid();
  actor_role text;
  kind_value text;
begin
  if actor is null then raise exception 'Sign in to leave a group.' using errcode='28000'; end if;
  select c.kind into kind_value from public.conversations c where c.id=target_conversation_id;
  if kind_value is distinct from 'group' then raise exception 'This action is only available for groups.' using errcode='22023'; end if;
  select cm.role into actor_role from public.conversation_members cm
   where cm.conversation_id=target_conversation_id and cm.user_id=actor;
  if actor_role is null then raise exception 'You are not a member of this group.' using errcode='P0002'; end if;
  if actor_role='owner' then raise exception 'Transfer group ownership before leaving.' using errcode='42501'; end if;
  delete from public.conversation_members where conversation_id=target_conversation_id and user_id=actor;
  delete from public.user_conversation_settings where conversation_id=target_conversation_id and user_id=actor;
end;
$function$
CREATE OR REPLACE FUNCTION public.log_message_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if old.body is distinct from new.body and old.deleted_at is null and old.recalled_at is null then
  insert into public.message_versions(message_id,editor_id,previous_body)
  values(old.id,coalesce((select auth.uid()),old.sender_id),old.body);
 end if;
 return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.lookup_chat_user(target_username text)
 RETURNS TABLE(id uuid, username text, display_name text, avatar_url text, bio text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare normalized_username text := lower(trim(coalesce(target_username,'')));
begin
  if auth.uid() is null then
    raise exception 'Sign in to search for people.' using errcode = '28000';
  end if;
  if normalized_username = '' then
    raise exception 'Enter a username to search.' using errcode = '22023';
  end if;
  if normalized_username !~ '^[a-z0-9_]{3,24}$' then
    raise exception 'Usernames must be 3–24 characters and use only letters, numbers, or underscores.' using errcode = '22023';
  end if;
  return query
    select p.id,p.username,p.display_name,p.avatar_url,p.bio
    from public.profiles p
    where lower(p.username)=normalized_username
    limit 1;
  if not found then
    raise exception 'No Luo Chat user was found with that username. Check the spelling and try again.' using errcode = 'P0002';
  end if;
end;
$function$
CREATE OR REPLACE FUNCTION public.manage_chat_group(target_conversation_id uuid, action text, target_username text DEFAULT NULL::text, target_user_id uuid DEFAULT NULL::uuid, new_role text DEFAULT NULL::text, new_title text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); actor_role text; person uuid; target_role text;
begin
 if actor is null then raise exception 'Sign in required.' using errcode='28000'; end if;
 perform 1 from public.conversations where id=target_conversation_id and kind='group' for update;
 if not found then raise exception 'Group not found.'; end if;
 select role into actor_role from public.conversation_members where conversation_id=target_conversation_id and user_id=actor;
 if actor_role is null or actor_role not in('owner','admin') then raise exception 'Group administrator required.' using errcode='42501'; end if;
 if action='rename' then
  if new_title is null or length(trim(new_title)) not between 1 and 100 then raise exception 'Use a group name of 1–100 characters.';end if;
  update public.conversations set title=trim(new_title) where id=target_conversation_id;
 elsif action='add' then
  select id into person from public.profiles where username=lower(trim(target_username));
  if person is null then raise exception 'Username not found.';end if;
  insert into public.conversation_members(conversation_id,user_id,role) values(target_conversation_id,person,'member') on conflict(conversation_id,user_id) do nothing;
 elsif action='role' then
  if actor_role<>'owner' then raise exception 'Only the owner can change roles.' using errcode='42501';end if;
  if target_user_id=actor or new_role is null or new_role not in('admin','member') then raise exception 'Invalid role change.';end if;
  select role into target_role from public.conversation_members where conversation_id=target_conversation_id and user_id=target_user_id;
  if target_role is null or target_role='owner' then raise exception 'Target member not eligible.';end if;
  update public.conversation_members set role=new_role where conversation_id=target_conversation_id and user_id=target_user_id;
 else raise exception 'Unknown group action.';end if;
end;$function$
CREATE OR REPLACE FUNCTION public.mark_conversation_read(target_conversation_id uuid, through_message_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); cutoff timestamptz:=now(); changed integer:=0; share_receipts boolean;
begin
 if actor is null or not public.is_conversation_member(target_conversation_id) then raise exception 'Conversation unavailable.' using errcode='42501';end if;
 if through_message_id is not null then select created_at into cutoff from public.chat_messages where id=through_message_id and conversation_id=target_conversation_id and deleted_at is null and recalled_at is null; if cutoff is null then raise exception 'Read-through message unavailable.';end if;end if;
 insert into public.chat_private_read_markers(user_id,conversation_id,read_through) values(actor,target_conversation_id,cutoff) on conflict(user_id,conversation_id) do update set read_through=greatest(public.chat_private_read_markers.read_through,excluded.read_through);
 select coalesce((select read_receipts from public.user_chat_settings where user_id=actor),true) into share_receipts;
 if share_receipts then
 insert into public.message_receipts(message_id,user_id,delivered_at,read_at) select m.id,actor,now(),now() from public.chat_messages m where m.conversation_id=target_conversation_id and m.sender_id<>actor and m.created_at<=cutoff and m.deleted_at is null and m.recalled_at is null and(m.expires_at is null or m.expires_at>now()) on conflict(message_id,user_id) do update set read_at=coalesce(public.message_receipts.read_at,excluded.read_at),delivered_at=coalesce(public.message_receipts.delivered_at,excluded.delivered_at);
 get diagnostics changed=row_count;
 end if;return changed;
end;$function$
