CREATE OR REPLACE FUNCTION public.remove_group_member(target_conversation_id uuid, target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := auth.uid();
  actor_role text;
  target_role text;
  kind_value text;
begin
  if actor is null then raise exception 'Sign in to manage this group.' using errcode='28000'; end if;
  select c.kind into kind_value from public.conversations c where c.id=target_conversation_id;
  if kind_value is distinct from 'group' then raise exception 'Member management is only available for groups.' using errcode='22023'; end if;
  select cm.role into actor_role from public.conversation_members cm
   where cm.conversation_id=target_conversation_id and cm.user_id=actor;
  if actor_role is null or actor_role not in ('owner','admin') then
    raise exception 'Only group owners and admins can remove members.' using errcode='42501';
  end if;
  select cm.role into target_role from public.conversation_members cm
   where cm.conversation_id=target_conversation_id and cm.user_id=target_user_id;
  if target_role is null then raise exception 'That user is not a member of this group.' using errcode='P0002'; end if;
  if target_user_id=actor then raise exception 'Use Leave group to remove yourself.' using errcode='22023'; end if;
  if target_role='owner' then raise exception 'The group owner cannot be removed. Transfer ownership first.' using errcode='42501'; end if;
  if actor_role='admin' and target_role='admin' then raise exception 'Admins cannot remove other admins.' using errcode='42501'; end if;
  delete from public.conversation_members where conversation_id=target_conversation_id and user_id=target_user_id;
  delete from public.user_conversation_settings where conversation_id=target_conversation_id and user_id=target_user_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.schedule_chat_text(target_conversation_id uuid, message_body text, scheduled_for timestamp with time zone, operation_id uuid, reply_to_message_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare existing public.scheduled_messages;
begin
 if auth.uid() is null or not public.is_conversation_member(target_conversation_id) then raise exception 'Conversation unavailable.' using errcode='42501';end if;
 if message_body is null or length(trim(message_body)) not between 1 and 10000 or scheduled_for is null or scheduled_for<=now() or scheduled_for>now()+interval '1 year' then raise exception 'Choose a future time within one year and a message of 1–10000 characters.';end if;
 if reply_to_message_id is not null and not exists(select 1 from public.chat_messages m where m.id=reply_to_message_id and m.conversation_id=target_conversation_id and m.deleted_at is null and m.recalled_at is null) then raise exception 'Reply target is unavailable.';end if;
 insert into public.scheduled_messages(id,conversation_id,sender_id,body,send_at,reply_to) values(operation_id,target_conversation_id,auth.uid(),message_body,scheduled_for,reply_to_message_id) on conflict(id) do nothing;
 select * into existing from public.scheduled_messages where id=operation_id;
 if existing.sender_id<>auth.uid() or existing.conversation_id<>target_conversation_id or existing.body<>message_body or existing.send_at<>scheduled_for or existing.reply_to is distinct from reply_to_message_id then raise exception 'Schedule operation conflict.';end if;
 return operation_id;
end;$function$
CREATE OR REPLACE FUNCTION public.search_my_chat_content(search_query text, max_results integer DEFAULT 50)
 RETURNS TABLE(result_type text, conversation_id uuid, message_id uuid, created_at timestamp with time zone, preview text, matched_text text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  q text := btrim(coalesce(search_query, ''));
  lim integer := greatest(1, least(coalesce(max_results, 50), 100));
BEGIN
  IF length(q) < 2 THEN
    RAISE EXCEPTION 'Search query must contain at least 2 characters'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH member_messages AS (
    SELECT m.id, m.conversation_id, m.sender_id, m.body, m.created_at
    FROM public.chat_messages m
    WHERE EXISTS (
      SELECT 1 FROM public.conversation_members cm
      WHERE cm.conversation_id = m.conversation_id
        AND cm.user_id = (SELECT auth.uid())
    )
      AND m.deleted_at IS NULL
      AND m.recalled_at IS NULL
  ),
  matches AS (
    SELECT 'message'::text AS kind, m.conversation_id AS conv_id, m.id AS msg_id,
      m.created_at AS happened_at, left(m.body, 240) AS preview_text, m.body AS matched
    FROM member_messages m
    WHERE coalesce(m.body, '') ILIKE '%' || q || '%'

    UNION ALL

    SELECT 'voice_transcript'::text, m.conversation_id, m.id, m.created_at,
      left(v.transcript, 240), v.transcript
    FROM public.voice_transcripts v
    JOIN member_messages m ON m.id = v.message_id
    WHERE coalesce(v.transcript, '') ILIKE '%' || q || '%'

    UNION ALL

    SELECT 'translation'::text, m.conversation_id, m.id, m.created_at,
      left(t.translated_text, 240), t.translated_text
    FROM public.message_translations t
    JOIN member_messages m ON m.id = t.message_id
    WHERE coalesce(t.translated_text, '') ILIKE '%' || q || '%'
      AND t.user_id = (SELECT auth.uid())

    UNION ALL

    SELECT 'attachment'::text, m.conversation_id, m.id, m.created_at,
      left(a.file_name, 240), concat_ws(' ', a.file_name, a.mime_type)
    FROM public.chat_attachments a
    JOIN member_messages m ON m.id = a.message_id
    WHERE coalesce(a.file_name, '') ILIKE '%' || q || '%'
       OR coalesce(a.mime_type, '') ILIKE '%' || q || '%'
  )
  SELECT kind, conv_id, msg_id, happened_at, preview_text, matched
  FROM matches
  ORDER BY happened_at DESC
  LIMIT lim;
END;
$function$
CREATE OR REPLACE FUNCTION public.search_my_chat_messages(search_query text, max_results integer DEFAULT 40)
 RETURNS TABLE(message_id uuid, conversation_id uuid, sender_id uuid, body text, message_type text, created_at timestamp with time zone, rank real)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select m.id,m.conversation_id,m.sender_id,m.body,m.message_type,m.created_at,
        ts_rank(to_tsvector('simple',coalesce(m.body,'')),websearch_to_tsquery('simple',search_query)) as rank
 from public.chat_messages m
 join public.conversation_members cm on cm.conversation_id=m.conversation_id and cm.user_id=(select auth.uid())
 where auth.uid() is not null and char_length(btrim(search_query))>0
   and m.deleted_at is null and m.recalled_at is null
   and to_tsvector('simple',coalesce(m.body,'')) @@ websearch_to_tsquery('simple',search_query)
 order by rank desc,m.created_at desc
 limit greatest(1,least(coalesce(max_results,40),100));
$function$
CREATE OR REPLACE FUNCTION public.send_chat_attachment(target_conversation_id uuid, operation_id text, message_body text, reply_to_message_id uuid, uploaded_path text, uploaded_name text, uploaded_type text, uploaded_bytes bigint, uploaded_checksum text)
 RETURNS chat_messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();stored storage.objects;msg public.chat_messages;kind text;
begin
 if actor is null or not public.is_conversation_member(target_conversation_id) then raise exception 'Conversation unavailable.' using errcode='42501';end if;
 if uploaded_path is distinct from target_conversation_id::text||'/'||actor::text||'/'||operation_id then raise exception 'Invalid upload path.';end if;
 if uploaded_name is null or length(trim(uploaded_name)) not between 1 and 255 or uploaded_bytes is null or uploaded_bytes not between 1 and 52428800 or uploaded_checksum is null or uploaded_checksum !~ '^[0-9a-f]{64}$' then raise exception 'Invalid attachment metadata.';end if;
 if uploaded_type is null or uploaded_type not in('image/jpeg','image/png','image/webp','image/gif','audio/mpeg','audio/mp4','audio/ogg','audio/webm','video/mp4','video/webm','application/pdf','text/plain') then raise exception 'Unsupported attachment type.';end if;
 select * into stored from storage.objects where bucket_id='chat-media' and name=uploaded_path;
 if stored.id is null or coalesce(stored.owner_id,stored.owner::text) is distinct from actor::text or(stored.metadata->>'size')::bigint is distinct from uploaded_bytes or stored.user_metadata->>'checksum' is distinct from uploaded_checksum then raise exception 'Upload is incomplete or does not match this file.';end if;
 kind:=case when uploaded_type like 'image/%' then 'image' when uploaded_type like 'audio/%' then 'audio' else 'file' end;
 msg:=public.send_chat_message_idempotent(target_conversation_id,operation_id,message_body,kind,reply_to_message_id);
 perform 1 from public.chat_messages where id=msg.id for update;
 if exists(select 1 from public.chat_attachments a where a.message_id=msg.id and(a.object_path<>uploaded_path or a.checksum is distinct from uploaded_checksum)) then raise exception 'Attachment retry conflicts with an existing file.';end if;
 if not exists(select 1 from public.chat_attachments where message_id=msg.id and object_path=uploaded_path) then insert into public.chat_attachments(message_id,conversation_id,uploader_id,object_path,file_name,mime_type,byte_size,checksum) values(msg.id,target_conversation_id,actor,uploaded_path,uploaded_name,uploaded_type,uploaded_bytes,uploaded_checksum);end if;
 return msg;
end;$function$
CREATE OR REPLACE FUNCTION public.send_chat_message_idempotent(target_conversation_id uuid, operation_id text, message_body text, message_kind text DEFAULT 'text'::text, reply_to_message_id uuid DEFAULT NULL::uuid)
 RETURNS chat_messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor uuid := (SELECT auth.uid());
  existing public.chat_messages;
  created public.chat_messages;
BEGIN
  IF actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;

  IF operation_id IS NULL OR length(operation_id) < 8 OR length(operation_id) > 160 THEN
    RAISE EXCEPTION 'operation_id must contain 8 to 160 characters' USING ERRCODE = '22023';
  END IF;

  IF message_body IS NULL OR length(message_body) < 1 OR length(message_body) > 10000 THEN
    RAISE EXCEPTION 'Message must contain 1 to 10000 characters' USING ERRCODE = '22023';
  END IF;

  IF message_kind NOT IN ('text','image','file','audio','system') THEN
    RAISE EXCEPTION 'Unsupported message type' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.conversation_members cm
    WHERE cm.conversation_id = target_conversation_id
      AND cm.user_id = actor
  ) THEN
    RAISE EXCEPTION 'You are not a member of this conversation' USING ERRCODE = '42501';
  END IF;

  IF reply_to_message_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.chat_messages parent
    WHERE parent.id = reply_to_message_id
      AND parent.conversation_id = target_conversation_id
      AND parent.deleted_at IS NULL
      AND parent.recalled_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Reply target is not an available message in this conversation' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.chat_messages (
    conversation_id, sender_id, body, message_type, reply_to, client_operation_id
  )
  VALUES (
    target_conversation_id, actor, message_body, message_kind, reply_to_message_id, operation_id
  )
  ON CONFLICT (sender_id, client_operation_id)
    WHERE client_operation_id IS NOT NULL
    DO NOTHING
  RETURNING * INTO created;

  IF created.id IS NOT NULL THEN
    RETURN created;
  END IF;

  SELECT * INTO existing
  FROM public.chat_messages m
  WHERE m.sender_id = actor
    AND m.client_operation_id = operation_id
  LIMIT 1;

  IF existing.id IS NULL THEN
    RAISE EXCEPTION 'Message retry conflict; retry the operation' USING ERRCODE = '40001';
  END IF;

  IF existing.conversation_id IS DISTINCT FROM target_conversation_id
     OR existing.body IS DISTINCT FROM message_body
     OR existing.message_type IS DISTINCT FROM message_kind
     OR existing.reply_to IS DISTINCT FROM reply_to_message_id THEN
    RAISE EXCEPTION 'operation_id was already used for a different message' USING ERRCODE = '23505';
  END IF;

  RETURN existing;
END;
$function$
