CREATE OR REPLACE FUNCTION public.set_my_chat_avatar(avatar_path text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  user_id uuid := auth.uid();
  result_url text;
begin
  if user_id is null then
    raise exception 'Authentication required';
  end if;

  if avatar_path is null or btrim(avatar_path) = '' then
    update public.profiles
       set avatar_url = null,
           updated_at = now()
     where id = user_id;
    if not found then raise exception 'Profile not found'; end if;
    return null;
  end if;

  if length(avatar_path) > 300
     or avatar_path !~ ('^' || user_id::text || '/[A-Za-z0-9_-]{1,100}[.](jpg|jpeg|png|webp)$') then
    raise exception 'Invalid avatar path';
  end if;

  result_url := 'https://byjixqwpjvsgmqilmzbm.supabase.co/storage/v1/object/public/avatars/' || avatar_path;

  update public.profiles
     set avatar_url = result_url,
         updated_at = now()
   where id = user_id;
  if not found then raise exception 'Profile not found'; end if;
  return result_url;
end;
$function$
CREATE OR REPLACE FUNCTION public.set_my_notification_preferences(new_direct_messages boolean, new_group_messages boolean, new_system_notifications boolean, new_quiet_hours_enabled boolean, new_quiet_hours_start time without time zone, new_quiet_hours_end time without time zone, new_time_zone text)
 RETURNS user_notification_preferences
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := auth.uid();
  result_row public.user_notification_preferences;
  zone_name text := trim(coalesce(new_time_zone,'UTC'));
begin
  if actor is null then raise exception 'Sign in to change notification settings.' using errcode='28000'; end if;
  if char_length(zone_name) < 1 or char_length(zone_name) > 64
     or not exists (select 1 from pg_catalog.pg_timezone_names z where z.name=zone_name) then
    raise exception 'Choose a valid time zone.' using errcode='22023';
  end if;
  if coalesce(new_quiet_hours_enabled,false)
     and (new_quiet_hours_start is null or new_quiet_hours_end is null) then
    raise exception 'Set both quiet-hours start and end times.' using errcode='22023';
  end if;
  insert into public.user_notification_preferences
    (user_id,direct_messages,group_messages,system_notifications,quiet_hours_enabled,quiet_hours_start,quiet_hours_end,time_zone,updated_at)
  values
    (actor,coalesce(new_direct_messages,true),coalesce(new_group_messages,true),coalesce(new_system_notifications,true),
     coalesce(new_quiet_hours_enabled,false),new_quiet_hours_start,new_quiet_hours_end,zone_name,now())
  on conflict (user_id) do update set
    direct_messages=excluded.direct_messages,
    group_messages=excluded.group_messages,
    system_notifications=excluded.system_notifications,
    quiet_hours_enabled=excluded.quiet_hours_enabled,
    quiet_hours_start=excluded.quiet_hours_start,
    quiet_hours_end=excluded.quiet_hours_end,
    time_zone=excluded.time_zone,
    updated_at=now()
  returning * into result_row;
  return result_row;
end;
$function$
CREATE OR REPLACE FUNCTION public.start_direct_chat(target_username text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me uuid := auth.uid();
  other_user uuid;
  existing_id uuid;
  new_id uuid;
  normalized_username text := lower(trim(coalesce(target_username,'')));
begin
  if me is null then raise exception 'Sign in to start a chat.' using errcode = '28000'; end if;
  if normalized_username = '' then raise exception 'Enter a username.' using errcode = '22023'; end if;
  if normalized_username !~ '^[a-z0-9_]{3,24}$' then
    raise exception 'Usernames must be 3–24 characters and use only letters, numbers, or underscores.' using errcode = '22023';
  end if;
  select p.id into other_user from public.profiles p where lower(p.username)=normalized_username;
  if other_user is null then
    raise exception 'No Luo Chat user was found with that username. Check the spelling and try again.' using errcode = 'P0002';
  end if;
  if other_user = me then raise exception 'You cannot start a chat with your own account.' using errcode = '22023'; end if;
  select c.id into existing_id
  from public.conversations c
  join public.conversation_members a on a.conversation_id=c.id and a.user_id=me
  join public.conversation_members b on b.conversation_id=c.id and b.user_id=other_user
  where c.kind='direct'
    and (select count(*) from public.conversation_members allm where allm.conversation_id=c.id)=2
  limit 1;
  if existing_id is not null then return existing_id; end if;
  insert into public.conversations(kind,created_by) values ('direct',me) returning id into new_id;
  insert into public.conversation_members(conversation_id,user_id,role)
  values (new_id,me,'owner'),(new_id,other_user,'member');
  return new_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.toggle_chat_reaction(target_message_id uuid, reaction text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();
begin
 if actor is null or reaction is null or reaction not in('👍','❤️','😂','🎉','😮','😢') then raise exception 'Choose a supported reaction.';end if;
 perform 1 from public.chat_messages m where id=target_message_id and public.is_conversation_member(m.conversation_id) and deleted_at is null and recalled_at is null and(expires_at is null or expires_at>now()) for update;
 if not found then raise exception 'Message unavailable.' using errcode='42501';end if;
 delete from public.message_reactions where message_id=target_message_id and user_id=actor and emoji=reaction;
 if found then return false;end if;
 insert into public.message_reactions(message_id,user_id,emoji) values(target_message_id,actor,reaction);return true;
end;$function$
