CREATE OR REPLACE FUNCTION public.transfer_group_ownership(target_conversation_id uuid, new_owner_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := auth.uid(); actor_role text; kind_value text;
begin
  if actor is null then raise exception 'Sign in to transfer ownership.' using errcode='28000'; end if;
  select c.kind into kind_value from public.conversations c where c.id=target_conversation_id;
  if kind_value is distinct from 'group' then raise exception 'Ownership transfer is only available for groups.' using errcode='22023'; end if;
  select cm.role into actor_role from public.conversation_members cm
   where cm.conversation_id=target_conversation_id and cm.user_id=actor;
  if actor_role is distinct from 'owner' then raise exception 'Only the current owner can transfer ownership.' using errcode='42501'; end if;
  if not exists (select 1 from public.conversation_members cm where cm.conversation_id=target_conversation_id and cm.user_id=new_owner_user_id) then
    raise exception 'The new owner must already be a group member.' using errcode='P0002';
  end if;
  update public.conversation_members set role='admin'
    where conversation_id=target_conversation_id and user_id=actor;
  update public.conversation_members set role='owner'
    where conversation_id=target_conversation_id and user_id=new_owner_user_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.update_my_chat_profile(new_username text, new_display_name text, new_bio text DEFAULT NULL::text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me uuid := auth.uid();
  clean_username text := lower(trim(coalesce(new_username, '')));
  clean_name text := trim(coalesce(new_display_name, ''));
  clean_bio text := trim(coalesce(new_bio, ''));
  result public.profiles;
begin
  if me is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if clean_username !~ '^[a-z0-9_]{3,24}$' then
    raise exception 'Username must be 3–24 characters using letters, numbers, and underscores';
  end if;
  if char_length(clean_name) < 1 or char_length(clean_name) > 60 then
    raise exception 'Display name must be 1–60 characters';
  end if;
  if char_length(clean_bio) > 240 then
    raise exception 'Bio must be at most 240 characters';
  end if;

  update public.profiles
  set username = clean_username,
      display_name = clean_name,
      bio = nullif(clean_bio, ''),
      updated_at = now()
  where id = me
  returning * into result;

  if not found then
    raise exception 'Profile not found';
  end if;
  return result;
exception
  when unique_violation then
    raise exception 'That username is already taken' using errcode = '23505';
end;
$function$
CREATE OR REPLACE FUNCTION public.vote_chat_simple_poll(target_poll_id uuid, target_option_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not exists(select 1 from public.chat_polls p join public.chat_messages m on m.id=p.message_id where p.id=target_poll_id and public.is_conversation_member(p.conversation_id) and m.deleted_at is null and m.recalled_at is null and(m.expires_at is null or m.expires_at>now())) then raise exception 'Poll unavailable.' using errcode='42501';end if;
 perform public.cast_chat_poll_vote(target_poll_id,array[target_option_id]);
end;$function$
